B.a_J=s([" \uc774 \ud750\ub984\uc744 \ubb34\ub9ac \uc5c6\uc774 \uc774\uc5b4\uac00\ub418, \uacfc\ubaa9 \uac04 \ud2c8\ud2c8\uc774 \ud734\uc2dd\ub3c4 \ucda9\ubd84\ud788 \ucc59\uaca8\uc8fc\uc2dc\uae38 \uad8c\ud574\ub4dc\ub9bd\ub2c8\ub2e4."," \ub2e4\ub9cc \uc7a5\uc2dc\uac04 \uc9d1\uc911\ud55c \ub4a4\uc5d0\ub294 \ucee8\ub514\uc158 \uad00\ub9ac\ub3c4 \ud568\uaed8 \uc2e0\uacbd \uc368\uc8fc\uc2dc\uba74 \ub354\uc6b1 \uc88b\uaca0\uc2b5\ub2c8\ub2e4."," \uc774\ub7f0 \ubc00\ub3c4 \uc788\ub294 \ud558\ub8e8\uac00 \uafb8\uc900\ud788 \uc313\uc774\uba74 \uc131\uc801 \ud5a5\uc0c1\uc73c\ub85c \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc774\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \ub192\uc2b5\ub2c8\ub2e4."],t.s)
B.a_5=s([" \uc9c0\uae08\uc758 \ud559\uc2b5 \ud398\uc774\uc2a4\ub97c \uafb8\uc900\ud788 \uc720\uc9c0\ud558\ub294 \uac83\uc744 \uad8c\uc7a5\ub4dc\ub9bd\ub2c8\ub2e4."," \uc0c1\ub300\uc801\uc73c\ub85c \ucde8\uc57d\ud55c \uacfc\ubaa9\uc5d0 \uc870\uae08 \ub354 \uc2dc\uac04\uc744 \ubc30\ubd84\ud574\ubcf4\ub294 \uac83\ub3c4 \uc88b\uc740 \uc120\ud0dd\uc774 \ub420 \uac83\uc785\ub2c8\ub2e4."," \uc548\uc815\uc801\uc778 \ud559\uc2b5 \uc2b5\uad00\uc774 \ucc28\uadfc\ucc28\uadfc \uc790\ub9ac\uc7a1\uc544\uac00\uace0 \uc788\ub294 \uac83\uc73c\ub85c \ud310\ub2e8\ub429\ub2c8\ub2e4."],t.s)
B.a_g=s([" \ub0b4\uc77c\uc740 \uc870\uae08 \ub354 \uc5ec\uc720 \uc788\uac8c \uc9d1\uc911 \uc2dc\uac04\uc744 \ud655\ubcf4\ud574\ubcf4\uc2dc\uae38 \uad8c\ud574\ub4dc\ub9bd\ub2c8\ub2e4."," \uc9e7\ub354\ub77c\ub3c4 \ub9e4\uc77c \uafb8\uc900\ud788 \uc774\uc5b4\uac00\ub294 \uc2b5\uad00\uc774 \uc7a5\uae30\uc801\uc73c\ub85c\ub294 \ub354 \uc911\uc694\ud569\ub2c8\ub2e4."," \ubd80\ub2f4\ub418\uc9c0 \uc54a\ub294 \uc120\uc5d0\uc11c \ud559\uc2b5 \uc2dc\uac04\uc744 \uc870\uae08\uc529 \ub298\ub824\uac00 \ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4."],t.s)
B.a07=s([" \ucee8\ub514\uc158\uc5d0 \ub530\ub77c \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub098\ud0c0\ub098\ub294 \ud750\ub984\uc77c \uc218 \uc788\uc73c\ub2c8 \ud06c\uac8c \uac71\uc815\ud558\uc9c0 \uc54a\uc73c\uc154\ub3c4 \ub429\ub2c8\ub2e4."," \ub0b4\uc77c\uc740 \uc88b\uc544\ud558\ub294 \uacfc\ubaa9\ubd80\ud130 \uac00\ubccd\uac8c \uc2dc\uc791\ud574\ubcf4\uc2dc\ub294 \uac83\uc744 \uad8c\ud574\ub4dc\ub9bd\ub2c8\ub2e4."," \uc9e7\uc740 \ud559\uc2b5\uc774\ub77c\ub3c4 \uafb8\uc900\ud788 \uc774\uc5b4\uc9c4\ub2e4\uba74 \uadf8 \uc790\uccb4\ub85c \ucda9\ubd84\ud788 \uc758\ubbf8 \uc788\ub294 \uc2b5\uad00\uc774 \ub429\ub2c8\ub2e4."],t.s)
