B.a_b=s(["\uc9c0\uae08\uae4c\uc9c0 \uc313\uc544\uc628 \ub178\ub825\uc744 \ubbff\uace0 \ud754\ub4e4\ub9bc \uc5c6\uc774 \uc815\uc9c4\ud55c\ub2e4\uba74, \uc55e\uc73c\ub85c\uc758 \ud3c9\uac00\uc5d0\uc11c\ub3c4 \ucda9\ubd84\ud788 \uc88b\uc740 \uacb0\uacfc\ub97c \uc774\uc5b4\uac08 \uc218 \uc788\uc744 \uac83\uc785\ub2c8\ub2e4.","\uc790\ub9cc\ud558\uc9c0 \uc54a\ub418 \uc790\uc2e0\uac10\uc744 \uc783\uc9c0 \uc54a\ub294 \uade0\ud615 \uc7a1\ud78c \ud0dc\ub3c4\ub85c \ub2e4\uc74c \ubaa9\ud45c\ub97c \ud5a5\ud574 \ub098\uc544\uac00\uc2dc\uae38 \uc751\uc6d0\ud569\ub2c8\ub2e4."],t.s)
B.a2M=s(["\uc9c0\uae08\uc758 \uc704\uce58\ub294 \uc815\uc0c1\uc73c\ub85c \uac00\ub294 \ub9c8\uc9c0\ub9c9 \uad00\ubb38\uc5d0 \uac00\uae4c\uc6b0\ub2c8, \uc870\uae08\ub9cc \ub354 \uc9d1\uc911\ub825\uc744 \ubc1c\ud718\ud55c\ub2e4\uba74 \ucda9\ubd84\ud788 \uc0c1\uc704\uad8c \uc9c4\uc785\uc774 \uac00\ub2a5\ud560 \uac83\uc785\ub2c8\ub2e4.","\uafb8\uc900\ud568\uc744 \uc783\uc9c0 \uc54a\ub294\ub2e4\uba74 \ub2e4\uc74c \ud3c9\uac00\uc5d0\uc11c\ub294 \uc9c0\uae08\ubcf4\ub2e4 \ud55c \ub2e8\uacc4 \ub354 \ub192\uc740 \uc131\ucde8\ub97c \ud655\uc778\ud560 \uc218 \uc788\uc744 \uac83\uc73c\ub85c \uae30\ub300\ub429\ub2c8\ub2e4."],t.s)
B.a_8=s(["\uc88c\uc808\ud560 \ud544\uc694\ub294 \uc804\ud600 \uc5c6\uc73c\uba70, \uc624\ud788\ub824 \uc9c0\uae08\uc774 \uac00\uc7a5 \uadf9\uc801\uc778 \ubc18\ub4f1\uc744 \ub9cc\ub4e4\uc5b4\ub0bc \uc218 \uc788\ub294 \uad6c\uac04\uc774\ub77c\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4.","\ubb38\uc81c\uc810\uc744 \uba85\ud655\ud788 \uc778\uc9c0\ud558\uace0 \uc788\ub294 \ub9cc\ud07c, \uc624\ub298\ubd80\ud130\uc758 \uc791\uc740 \ubcc0\ud654\uac00 \ub2e4\uc74c \ud3c9\uac00\uc5d0\uc11c \ub208\uc5d0 \ub744\ub294 \uacb0\uacfc\ub85c \uc774\uc5b4\uc9c8 \uac83\uc785\ub2c8\ub2e4."],t.s)
B.a2G=s(["\uc9c0\uae08\uc758 \uacbd\uac01\uc2ec\uc744 \ubcc0\ud654\uc758 \ubc1c\ud310\uc73c\ub85c \uc0bc\ub294\ub2e4\uba74, \ucda9\ubd84\ud788 \ubc18\ub4f1\ud560 \uc218 \uc788\ub294 \uc704\uce58\uc5d0 \uc788\ub2e4\ub294 \uc810\uc744 \uc78a\uc9c0 \uc54a\uc73c\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4.","\ub098\ud0dc\ud568\uc5d0 \ube60\uc9c0\uc9c0 \uc54a\uace0 \uc624\ub298\ubd80\ud130 \uc9d1\uc911\ub3c4\ub97c \ub04c\uc5b4\uc62c\ub9b0\ub2e4\uba74, \ub2e4\uc74c \ud3c9\uac00\uc5d0\uc11c\ub294 \ubd84\uba85\ud788 \ub2e4\ub978 \uacb0\uacfc\ub97c \ud655\uc778\ud560 \uc218 \uc788\uc744 \uac83\uc785\ub2c8\ub2e4."],t.s)
B.a_N=s(["\uc9c0\uae08\uc758 \uc5b4\ub824\uc6c0\uc740 \uae30\ucd08\ub97c \ub2e4\uc2dc \ub2e4\uc9c0\ub294 \uacfc\uc815\uc5d0\uc11c \ub204\uad6c\ub098 \uacaa\uc744 \uc218 \uc788\ub294 \ub2e8\uacc4\uc774\ub2c8, \ud3ec\uae30\ud558\uc9c0 \uc54a\uace0 \uafb8\uc900\ud788 \ub098\uc544\uac00\ub294 \uac83\uc774 \uac00\uc7a5 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc791\uc740 \uc9c4\uc804\uc774\ub77c\ub3c4 \uafb8\uc900\ud788 \uc313\uc778\ub2e4\uba74 \ubc18\ub4dc\uc2dc \ub208\uc5d0 \ubcf4\uc774\ub294 \ubcc0\ud654\ub85c \uc774\uc5b4\uc9c8 \uac83\uc774\ub2c8, \uc870\uae09\ud574\ud558\uc9c0 \uc54a\uace0 \ud568\uaed8 \ub098\uc544\uac00\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4."],t.s)
